const body = $json.body || {};
const profile = body.profile || {};
const scheme = body.scheme || {};
const docs = Array.isArray(body.document_statuses) ? body.document_statuses : [];

const application = {
  status: 'draft_for_review',
  applicant: {
    full_name: profile.full_name || '',
    state: profile.state || '',
    occupation: profile.occupation || '',
    income: profile.income != null ? profile.income : null,
    need: profile.need || '',
  },
  scheme: {
    id: scheme.id || '',
    name: scheme.name || '',
    benefits: scheme.benefits || '',
    application_method: scheme.application_method || '',
    source_url: scheme.source_url || '',
  },
  documents: docs.map((d) => ({
    document_type: (d && d.document_type) || '',
    status: (d && d.status) || 'missing',
    note: (d && d.note) || '',
  })),
  document_summary: {
    total: docs.length,
    present: docs.filter((d) => d && d.status === 'present').length,
    outstanding: docs.filter((d) => d && d.status && d.status !== 'present').length,
  },
  disclaimer: 'This is a draft assembled for human review only. It has not been submitted to any government portal.',
};

return { json: application };
